const traceRows=[];
for(const line of direct.slice(0,30)){
  const c=runtime.cases.find(x=>x.id===line.caseId); const original=line.original||line.text; const review=candidates.find(x=>x.ru_excerpt===original); const stored=review?reviews.find(x=>x.id===review.id):null;
  let visible='NOT_SURFACED';
  try{await page.selectOption('#caseSelector',line.caseId,{timeout:3000});await page.waitForTimeout(60);await page.locator('#sourceBtn').click({timeout:3000});const b=page.locator('#caseEvidenceList button').filter({hasText:line.text}).first();if(await b.count()){await b.click({timeout:3000});visible=await page.locator('#sourceTranslation').textContent();}await page.locator('#closeDrawer').click({timeout:3000});}catch{}
  traceRows.push({case_id:line.caseId,source_id:line.source_ids?.[0]||'',excerpt_id:review?.id||'',translation_id:review?.id||'',stored_ru:original,stored_ko:stored?.natural_ko||'',runtime_lookup_key:line.source_ids?.[0]||'',runtime_returned_ko:line.text,visible_ko:visible,match_expected:visible==='NOT_SURFACED'?'not_rendered':visible===line.text?'match':'mismatch',duplicate_with_other_excerpt:false,suspected_failure_point:visible==='NOT_SURFACED'?'case evidence not surfaced by current UI path':'source-reading uses runtime line text as translation'});
}
