const dup=new Map();for(const x of traceRows){if(!dup.has(x.runtime_returned_ko))dup.set(x.runtime_returned_ko,[]);dup.get(x.runtime_returned_ko).push(x.excerpt_id);}for(const x of traceRows)x.duplicate_with_other_excerpt=(dup.get(x.runtime_returned_ko)||[]).length>1;
await put('04_translation/TRANSLATION_TRACE.csv',csv(traceRows,Object.keys(traceRows[0])));

// Source exports.
