const sourceRows=[...srcMap.values()].map(s=>({source_id:s.id,case_ids:corpus.casePacks.filter(c=>c.sourceObjectIds?.includes(s.id)).map(c=>c.id),title_ru:s.title_ru||s.repository||'',title_ko:s.title_ko||'',date:s.date||'',author_or_issuer:s.author_or_issuer||'',publication:s.publication||'',volume:s.volume||'',issue:s.issue||'',page:s.page||'',archive:s.archive||'',catalog_id:s.catalog_id||'',stable_url:s.stable_url||s.url||'',scan_url:s.scan_url||'',source_type:s.source_type||s.tier||'',rights:s.rights||'',has_scan:Boolean(s.scan_url||s.binaryUsed),runtime_used:usedSourceIds.has(s.id),notes:s.locator||s.source_context_note||''}));
const sourceFields=Object.keys(sourceRows[0]);await put('03_sources/sources.csv',csv(sourceRows,sourceFields));
const reviewMap=new Map(reviews.map(x=>[x.id,x.natural_ko]));const exUnits=[...corpus.excerptUnits,...candidates.map(x=>({...x,natural_ko:reviewMap.get(x.id)||''}))];const exSeen=new Set();const exRows=exUnits.filter(x=>{if(exSeen.has(x.id))return false;exSeen.add(x.id);return true;}).map(x=>({excerpt_id:x.id,source_id:x.sourceObjectId||'',case_id:corpus.casePacks.filter(c=>c.sourceObjectIds?.includes(x.sourceObjectId)).map(c=>c.id).join(';'),ru_text:x.ru_excerpt||'',ko_text:x.natural_ko||'',translation_id:x.id,page:x.page||x.locator||'',context:x.source_context_note||'',runtime_used:runtime.cases.some(c=>c.lines.some(l=>l.original===x.ru_excerpt||l.text===x.natural_ko)),evidence_class:x.evidence_class||'',notes:x.translation_status||''}));
