const matrix=corpus.casePacks.map(c=>({case_id:c.id,title_ko:c.title_ko,year:c.year,source_ids:c.sourceObjectIds,excerpt_ids:exRows.filter(e=>e.case_id.split(';').includes(c.id)).map(e=>e.excerpt_id)}));await put('03_sources/case_source_matrix.csv',csv(matrix,Object.keys(matrix[0])));
await put('03_sources/SOURCE_CATALOG.md',`# Source catalog\n\nThis is a generated catalog of ${sourceRows.length} deduplicated source objects/records. It distinguishes runtime-linked IDs from corpus-only records through the 'runtime_used' column in sources.csv.\n\n## Tier 1 — direct runtime use\n\n${sourceRows.filter(x=>x.runtime_used).map(x=>`- **${x.source_id}** — ${x.title_ko||x.title_ru}; ${x.date}; ${x.source_type}; ${x.stable_url||'no stable URL'}; cases: ${x.case_ids||'runtime-only ID'}.`).join('\n')}\n\n## Tier 2 — corpus/case material not directly exposed on this route\n\n${sourceRows.filter(x=>!x.runtime_used&&x.case_ids).slice(0,120).map(x=>`- **${x.source_id}** — ${x.title_ko||x.title_ru}; ${x.date}; ${x.source_type}; ${x.stable_url||'no stable URL'}; cases: ${x.case_ids}.`).join('\n')}\n\n## Tier 3 — research/reference only\n\n${sourceRows.filter(x=>!x.runtime_used&&!x.case_ids).map(x=>`- **${x.source_id}** — ${x.title_ko||x.title_ru}; ${x.date}; ${x.source_type}; ${x.stable_url||'no stable URL'}; rights: ${x.rights}.`).join('\n')}\n\nThe bundle contains metadata and URLs only; no uncertain-rights scans were redistributed.\n`);

const transItems=exRows.slice(0,120);await put('04_translation/ALL_TRANSLATIONS.md',transItems.map(x=>`## ${x.excerpt_id}\n\nCase: ${x.case_id}\nSource: ${x.source_id}\nPage: ${x.page}\n\n### Russian\n${x.ru_text||'(missing)'}\n\n### Korean currently stored\n${x.ko_text||'(missing)'}\n\n### Korean currently visible in runtime\n${traceRows.find(t=>t.excerpt_id===x.excerpt_id)?.visible_ko||'not independently surfaced in sampled route'}\n\n### Status\n- ${x.ko_text?'stored translation present':'missing'}\n- ${x.runtime_used?'runtime-linked':'not directly runtime-linked in sampled route'}\n\n### Notes\nEvidence class: ${x.evidence_class}; source context: ${x.context}\n`).join('\n'));
await put('04_translation/TRANSLATION_BUG_REPORT.md',`# Translation bug report\n\n## Reproduction\n\n1. Open the app at ${base}.\n2. Select a case in the case selector.\n3. Open 자료 맥락 열기 and select an evidence excerpt.\n4. Compare sourceTranscription, sourceTranslation, and the stored excerpt review record.\n\n## Observed result\n\nThe 30-row trace records the current data/runtime/UI path without modifying any translation. Direct runtime lines carry 'original' and Korean 'text', while the source-reading path receives 'translation: line.text' from 'mountCaseEvidence'. The sampled route therefore often exposes the runtime line rather than an independent translation_id lookup. Rows that could not be surfaced are explicitly marked 'NOT_SURFACED'.\n\n## First suspicious layer\n\nThe first suspicious layer is the source-reading adapter in app.js ('mountCaseEvidence' and 'setSourceReading'), because it assigns the runtime line text directly to the translation field. This is a diagnostic finding, not a fix.\n\n## Other candidates inspected\n\n- sourceId/excerptId/translationId: excerpt review IDs exist, but runtime lines use source_ids and do not carry a separate translation_id.\n- fallback constant: scene render uses a scene-level translation string for the paper.\n- route stale state: the app wraps renderCase/renderScene multiple times; this is a route-state risk.\n- index lookup: case evidence uses filtered array positions for visible buttons.\n- duplicate IDs: duplicate source/excerpt IDs are represented in the exported rows and corpus audit.\n\n## Confidence\n\nMedium confidence for the adapter mismatch; low confidence for stale state or collision as the primary cause until an independent per-excerpt UI test is run.\n`);

